+    --series-5:#199e70; --series-6:#d95926; --series-7:#9085e9; --series-8:#e66767;
+    color-scheme:dark;
+  }
+}
+:root[data-theme="dark"] {
+  --surface-1:#1a1a19; --plane:#0d0d0d; --ink:#fff; --ink-2:#c3c2b7; --muted:#898781;
+  --grid:#2c2c2a; --axis:#383835; --border:rgba(255,255,255,.10);
